'use strict';
const STORE_FACTORS={Aldi:1,Lidl:1.01,Tesco:1.13,Asda:1.10,"Sainsbury's":1.17,Morrisons:1.15,"Marks & Spencer (M&S)":1.30,'My store':1};
const DAYS=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const ALLERGENS=['dairy','gluten','egg','fish','shellfish','soy','nuts','sesame','mustard'];
const APPLIANCES=['hob','oven','airfryer','microwave'];
const UNITLABEL={g:'g',ml:'ml',each:''};
const KEY='platepilot_v1';
const MS_STORE='Marks & Spencer (M&S)';
const PRICE_TTL=24*60*60*1000;
let WIZARD_STEP=0,priceBusy=false,priceStatus='',lastAutoPriceTry=0;
function defaultState(){return {budget:55,store:'Marks & Spencer (M&S)',servings:2,diet:'any',priorities:['quick','family'],allergens:[],appliances:['hob','oven','airfryer','microwave'],avoid:'',pantry:['oil','salt','peppercorn','paprika','cumin','oregano'],plans:{},checked:{},manual:{},favourites:[],custom:[],customIngredients:{},tab:'plan',theme:'dark',onboarded:false,foods:['meat','fish','vegetarian','vegan','egg'],timeCap:45,livePrices:{},lastLiveAt:0,weekOffset:0,filter:'all',query:'',shopWeeks:1,shopMode:'plan',startDay:1,cooked:{},planLength:7,tonightMeal:null,quickType:'any',quickTime:30,quickGoal:'any',quickFamily:false,quickSeed:0}}
let S=defaultState(),MODAL=null,timerEnd=0,timerTick=null,toastTimeout=null;
try{const raw=localStorage.getItem(KEY);if(raw){const d=JSON.parse(raw);if(d&&typeof d==='object')S={...defaultState(),...d}}}catch(e){console.warn('Could not restore saved data',e)}
const app=document.getElementById('app');
function esc(v){return String(v??'').replace(/[&<>"']/g,s=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[s]))}
function money(n){return '£'+Number(n||0).toFixed(2)}
function clone(v){return JSON.parse(JSON.stringify(v))}
function save(){try{localStorage.setItem(KEY,JSON.stringify(S))}catch(e){toast('Storage is full — export a backup from Settings')}}
function toast(msg){let t=document.getElementById('toast');t.textContent=msg;t.classList.add('on');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>t.classList.remove('on'),2600)}
function localDate(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function parseDate(iso){const [y,m,d]=iso.split('-').map(Number);return new Date(y,m-1,d,12)}
function addDays(d,n){let x=new Date(d);x.setDate(x.getDate()+n);return x}
function startOfWeek(d=new Date()){let t=new Date(d);t.setHours(12,0,0,0);t.setDate(t.getDate()-((t.getDay()-S.startDay+7)%7));return t}
function wk(offset=S.weekOffset){return localDate(addDays(startOfWeek(),offset*7))}
function planLength(key=wk()){return Math.max(1,Math.min(28,Number(S.plans[key]?.days?.length||S.planLength||7)))}
function weekDays(key=wk()){return Array.from({length:planLength(key)},(_,i)=>addDays(parseDate(key),i))}
function weekLabel(key=wk()){const dd=weekDays(key);const fmt=d=>d.toLocaleDateString('en-GB',{day:'numeric',month:'short'});return fmt(dd[0])+(dd.length>1?' – '+fmt(dd[dd.length-1]):'')}
function allR(){return [...BUILTIN,...(S.custom||[])]}
function recipe(id){return allR().find(r=>r.id===id)}
function ingredient(id){return ING[id]||(S.customIngredients||{})[id]}
function baseUnit(x){return x.unit==='each'?1:100}
function recipeMacros(r,servings=S.servings){return {kcal:Math.round(r.kcal),protein:Math.round(r.protein),carbs:Math.round(r.carbs),fat:Math.round(r.fat)}}
function lookupPrice(id,ing){const x=S.store===MS_STORE?(S.livePrices||{})[id]:null;return x&&x.pack>0&&x.price>0&&x.unit===ing.unit&&Date.now()-new Date(x.checkedAt||0).getTime()<=PRICE_TTL?x:null}
function shopUnitPrice(id,ing){let live=lookupPrice(id,ing);return live?{pack:live.pack,price:live.price,source:'live',product:live}: {pack:ing.pack,price:ing.price*(STORE_FACTORS[S.store]||1),source:'estimate',product:null}}
function basketDeal(up,packs){
 const base=packs*up.price, prod=up.product;
 if(!prod)return {price:base,saved:0,deal:''};
 // A multibuy only counts when this same product satisfies the entire required quantity.
 let best=base,deal='';
 for(const offer of prod.multibuys||[]){const n=Number(offer.quantity),price=Number(offer.price);if(n>=2&&Number.isInteger(n)&&price>0&&price<n*up.price&&packs>=n){let total=Math.floor(packs/n)*price+(packs%n)*up.price;if(total<best){best=total;deal=offer.text||`Buy ${n} for ${money(price)}`}}}
 const was=Number(prod.wasPrice);const original=was>up.price?packs*was:base;
 return {price:best,saved:Math.max(0,original-best),deal:deal||(was>up.price?`Was ${money(was)} / pack`:''),previous:original};
}
function recipeActualCost(r, servings=S.servings){if(!r)return 0;return r.ingredients.reduce((sum,x)=>{if(S.pantry.includes(x.id))return sum;let ing=ingredient(x.id);if(!ing)return sum;const up=shopUnitPrice(x.id,ing);return sum+(x.qty*servings/2/up.pack)*up.price},0)}
function allergens(r){let out=new Set();for(let x of r.ingredients){let ing=ingredient(x.id);(ing?.allergens||[]).forEach(a=>out.add(a))}return [...out]}
function eligible(){let avoid=S.avoid.toLowerCase().split(',').map(x=>x.trim()).filter(Boolean);return allR().filter(r=>{
  if(S.diet==='vegan'&&r.diet!=='vegan')return false;
  if(S.diet==='vegetarian'&&!['vegan','vegetarian'].includes(r.diet))return false;
  if(S.diet==='pescatarian'&&r.diet==='meat')return false;
  if(S.diet==='lowcarb'&&r.carbs>36)return false;
  const foods=Array.isArray(S.foods)?S.foods:['meat','fish','vegetarian','vegan','egg'];
  const foodType=(r.diet==='meat'?'meat':r.diet==='fish'?'fish':r.diet==='vegan'?'vegan':'vegetarian');
  if(!foods.includes(foodType)&&!(foods.includes('egg')&&r.ingredients.some(x=>x.id==='egg')))return false;
  if(r.minutes>(Number(S.timeCap)||60))return false;
  if(S.priorities.includes('family')&&/spicy|sriracha|firecracker|jalapeño|jalapeno/i.test(r.title))return false;
  if(S.allergens.some(a=>allergens(r).includes(a)))return false;
  if(avoid.some(term=>r.title.toLowerCase().includes(term)||r.ingredients.some(x=>ingredient(x.id)?.name.toLowerCase().includes(term))))return false;
  if(r.method==='tray'||r.method==='oven')return S.appliances.includes('oven')||S.appliances.includes('airfryer');
  return S.appliances.includes('hob');
})}
function planDays(key=wk()){if(key==='tonight')return S.tonightMeal?[S.tonightMeal]:[];return S.plans[key]?.days||Array(planLength(key)).fill(null)}
function ensurePlan(key=wk()){if(!S.plans[key])S.plans[key]={days:Array(planLength(key)).fill(null),created:Date.now()};return S.plans[key]}
function grocery(weeks=[wk()]){
  const map=new Map();
  for(let key of weeks){for(let rid of planDays(key)){const r=recipe(rid);if(!r)continue;for(let {id,qty} of r.ingredients){if(!qty||S.pantry.includes(id))continue;let ing=ingredient(id);if(!ing)continue;if(!map.has(id))map.set(id,{id,ing,qty:0,price:0,packs:0});map.get(id).qty+=qty*S.servings/2}}}
  const factor=STORE_FACTORS[S.store]||1;
  const list=[...map.values()].map(x=>{let u=shopUnitPrice(x.id,x.ing);let packs=Math.ceil(x.qty/u.pack), deal=basketDeal(u,packs);return {...x,packs,price:deal.price,saved:deal.saved,offerLabel:deal.deal,source:u.source,matched:u.product,packSize:u.pack}});
  for(let key of weeks){for(let x of (S.manual[key]||[])){list.push({id:'extra-'+key+'-'+x.id,ing:{name:x.name,unit:'each',pack:1,aisle:'Extras'},qty:x.qty,packs:x.qty,price:x.price*x.qty,manual:true})}}
  return list.sort((a,b)=>a.ing.aisle.localeCompare(b.ing.aisle)||a.ing.name.localeCompare(b.ing.name));
}
function groceryTotal(weeks=[wk()]){return grocery(weeks).reduce((s,x)=>s+x.price,0)}
function randomSample(pool,n){const a=pool.slice();for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a.slice(0,n)}
function chooseWeek(){const pool=eligible();if(!pool.length)return null;let target=S.budget*0.85,best=null,bestScore=Infinity;let n=Math.max(1,Math.min(28,Number(S.planLength)||7));
  for(let j=0;j<450;j++){
    const cand=Array.from({length:n},()=>pool[Math.floor(Math.random()*pool.length)]);let seen=new Set();for(let i=0;i<cand.length&&i<pool.length;i++){if(seen.has(cand[i].id)){let fresh=pool.find(r=>!seen.has(r.id));if(fresh)cand[i]=fresh}seen.add(cand[i].id)}let tmp=cand.map(r=>r.id);let totals=estimateGrocery(tmp);
    const over=Math.max(0,totals-S.budget),diversity=new Set(cand.map(x=>x.diet)).size;
    const distinct=new Set(cand.map(x=>x.method)).size;
    let preference=cand.reduce((p,r)=>p+(S.priorities.includes('quick')&&r.minutes>30?2.2:0)+(S.priorities.includes('protein')&&r.protein<30?3:0)+(S.priorities.includes('healthy')&&r.kcal>650?2:0)+(S.priorities.includes('family')&&/spicy|hot|chilli|jalape|sriracha/i.test(r.title)?3:0)+(S.priorities.includes('budget')&&recipeActualCost(r)>5?2:0),0);
    let offerBoost=cand.reduce((sum,r)=>sum+r.ingredients.reduce((v,x)=>{let p=S.livePrices?.[x.id];return v+(p?.wasPrice>p?.price?0.4:0)},0),0);let score=over*35+Math.abs(totals-target)*.32+(4-diversity)*2+(5-distinct)*.9+preference-offerBoost+Math.random()*4;
    if(score<bestScore){bestScore=score;best=tmp}
  }
  return best;
}
function estimateGrocery(ids){let sums={};for(let id of ids){const r=recipe(id);if(!r)continue;for(let x of r.ingredients){if(S.pantry.includes(x.id)||!x.qty)continue;sums[x.id]=(sums[x.id]||0)+x.qty*S.servings/2}}return Object.entries(sums).reduce((tot,[id,qty])=>{const i=ingredient(id);const u=shopUnitPrice(id,i);return tot+basketDeal(u,Math.ceil(qty/u.pack)).price},0)}
function generate(key=wk()){let chosen=chooseWeek();if(!chosen?.length){toast('No recipes match these restrictions. Update your preferences.');return false}let p=ensurePlan(key);p.days=Array.from({length:Math.max(1,Math.min(28,S.planLength))},(_,i)=>chosen[i%chosen.length]);p.created=Date.now();S.checked[key]={};S.cooked[key]={};save();return true}
// The first week is created after the setup questions are completed, never before.
// These original flat recipe illustrations are category examples, not exact finished dishes.
function photoFor(r){
  if(!r)return null;
  const x=new Set(r.ingredients.map(v=>v.id));const has=(...v)=>v.some(k=>x.has(k));
  if(has('salmon'))return 'salmon';
  if(has('cod','tuna'))return 'white-fish';
  if(has('prawns'))return r.method==='curry'?'chickpea-curry':'prawn-pasta';
  if(has('chicken','thigh'))return r.method==='curry'?'chickpea-curry':'chicken';
  if(has('beef','turkey','sausage'))return has('pasta','gnocchi')?'meatball-pasta':'beef-bowl';
  if(has('tofu'))return 'tofu-noodles';
  if(has('halloumi','feta'))return 'halloumi-bowl';
  if(has('egg'))return 'shakshuka';
  if(has('mushroom')&&has('pasta','gnocchi'))return 'mushroom-pasta';
  if(has('chickpeas','lentils','blackbeans','kidney')&&['curry','stew'].includes(r.method))return 'chickpea-curry';
  if(has('pasta','gnocchi'))return 'mushroom-pasta';
  if(has('rice_noodles','noodles'))return 'tofu-noodles';
  return 'vegetable-bowl';
}
function getArt(r,cls=''){
  let key=photoFor(r),photo=key?'assets/recipes/'+key+'.webp':null;
  return `<div class="food-art food-photo illustration ${cls}" aria-hidden="true">${photo?`<img src="${photo}" alt="" loading="lazy" decoding="async" draggable="false">`:`<span>${r?esc(r.emoji):'🍽️'}</span>`}</div>`;
}
function applyTheme(){
  const theme=S.theme==='light'?'light':'dark';document.documentElement.dataset.theme=theme;
  document.querySelector('meta[name="theme-color"]')?.setAttribute('content',theme==='dark'?'#101418':'#f7f5ef');
  document.querySelector('meta[name="apple-mobile-web-app-status-bar-style"]')?.setAttribute('content',theme==='dark'?'black-translucent':'default');
  const iconPath=`assets/icon-${theme}-192.png`;
  const touchPath=`assets/icon-${theme}-180.png`;
  const touchIcon=document.getElementById('apple-touch-icon');
  if(touchIcon&&touchIcon.getAttribute('href')!==touchPath)touchIcon.setAttribute('href',touchPath);
  const favicon=document.getElementById('app-favicon');
  if(favicon&&favicon.getAttribute('href')!==iconPath)favicon.setAttribute('href',iconPath);
  const manifest=document.getElementById('app-manifest');
  const path=theme==='dark'?'manifest.webmanifest':'manifest-light.webmanifest';
  if(manifest&&manifest.getAttribute('href')!==path)manifest.setAttribute('href',path);
}

function icon(key){return ({plan:'▦',tonight:'⚡',shop:'☷',discover:'⌕',profile:'⚙'})[key]||'◦'}
function nav(){let labels={plan:'My plan',tonight:'Tonight',shop:'Shopping',discover:'Recipes',profile:'Settings'};return Object.keys(labels).map(key=>`<button class="nav-item ${S.tab===key?'selected':''}" data-action="tab" data-value="${key}" ${S.tab===key?'aria-current="page"':''}><span class="nav-icon">${icon(key)}</span><span>${labels[key]}</span></button>`).join('')}
function brand(){return `<div class="logo"><span class="brand-symbol"><img class="logo-mark-img logo-variant-light" src="assets/pp-logo-light.svg" alt="PlatePilot logo"><img class="logo-mark-img logo-variant-dark" src="assets/pp-logo-dark.svg" alt="" aria-hidden="true"></span>PlatePilot</div>`}
function header(){return `<div class="topbar">${brand()}<div class="top-actions"><button class="theme-toggle" data-action="theme" aria-label="Switch to ${S.theme==='dark'?'light':'dark'} mode" aria-pressed="${S.theme==='dark'}"><span class="theme-icon">${S.theme==='dark'?'☾':'☀'}</span><span class="theme-label">${S.theme==='dark'?'Dark':'Light'}</span></button><button class="avatar" data-action="tab" data-value="profile" aria-label="Settings">P</button></div></div>`}
function shell(inner){return `<div class="app-shell"><aside class="sidebar">${brand()}<nav class="sidebar-nav">${nav()}</nav><div class="sidebar-tip"><strong>Made for real life ✳</strong>Flexible meal plans, spontaneous dinners and no monthly bill.</div></aside><main class="main">${header()}<div class="page">${inner}<div class="footer-note">PlatePilot · Private on this device · No subscriptions</div></div></main></div><nav class="bottom-nav" aria-label="Main navigation">${nav()}</nav>${MODAL?modalHTML():''}`}
function daysCard(){let key=wk(),dd=weekDays(key);return planDays(key).map((rid,i)=>{let r=recipe(rid),dt=dd[i],completed=!!S.cooked[key]?.[i],liked=r&&S.favourites.includes(r.id);return `<article class="day-card ${completed?'done':''}"><div class="day-pill"><strong>${DAYS[dt.getDay()].slice(0,3)}</strong><b>${dt.getDate()}</b></div>${r?`${getArt(r,'day-art')}<div class="day-info" data-action="detail" data-id="${r.id}" role="button" tabindex="0"><span class="eyebrow">${completed?'✓ COOKED':'DINNER'}</span><h3>${esc(r.title)}</h3><div class="pillrow"><span class="micro-pill">◷ ${r.minutes} min</span><span class="micro-pill green">${r.protein}g protein</span></div></div><div class="day-tools"><button class="round-action ${liked?'liked':''}" title="${liked?'Remove favourite':'Favourite'}" data-action="fav" data-id="${r.id}">${liked?'♥':'♡'}</button><button class="round-action" title="Swap meal" data-action="swap" data-day="${i}">⇄</button><button class="round-action" title="${completed?'Mark not cooked':'Mark cooked'}" data-action="cooked" data-day="${i}">${completed?'↶':'✓'}</button></div>`:`<div class="day-empty"><strong>No meal planned</strong><span>Choose something delicious</span></div><button class="iconbtn" data-action="choose-day" data-day="${i}" aria-label="Add meal">＋</button>`}</article>`}).join('')}
function weekPicker(){let key=wk();return `<div class="week-picker"><button class="iconbtn" data-action="week" data-value="-1" aria-label="Previous week">‹</button><div class="wk-title">${weekLabel(key)}<span>${key===wk(0)?'This week':key===wk(1)?'Next week':'Meal plan'}</span></div><button class="iconbtn" data-action="week" data-value="1" aria-label="Next week">›</button></div>`}
function planPage(){let key=wk(),has=planDays(key).some(Boolean),total=groceryTotal([key]),ratio=S.budget?total/S.budget:0,under=total<=S.budget;let rs=planDays(key).map(recipe).filter(Boolean),avgKcal=rs.length?Math.round(rs.reduce((s,r)=>s+r.kcal,0)/rs.length):0,avgProt=rs.length?Math.round(rs.reduce((s,r)=>s+r.protein,0)/rs.length):0;
return `<span class="eyebrow">MAKE DINNER EASY</span><h1 class="hero-title">Your meals,<br><em>sorted.</em></h1><p class="subheading">Choose 1–28 days, or find something delicious just for tonight.</p>${weekPicker()}<div class="budget-card"><div class="budget-top"><div><div class="lbl">Estimated grocery spend</div><div class="budget-value">${money(total)} <small>/ ${money(S.budget)}</small></div></div><span class="budget-tag">${under?'✓ Within budget':'! Over budget'}</span></div><div class="budget-track"><i class="${under?'':'over'}" style="width:${Math.min(100,ratio*100)}%"></i></div><div class="budget-foot"><span>Shopping at ${esc(S.store)} · ${S.servings} ${S.servings===1?'person':'people'}</span><span>${under?money(S.budget-total)+' left':money(total-S.budget)+' over'}</span></div></div><button class="generate" data-action="generate"><span style="font-size:20px">✦</span> ${has?'Answer questions & plan again':'Plan my meals'} <span>→</span></button><button class="btn light full tonight-shortcut" data-action="tab" data-value="tonight">⚡ Only need dinner tonight? Find one meal →</button>${has?`<div class="weekly-summary"><div><strong>${rs.length}/${planLength(key)}</strong><span>Dinners planned</span></div><div><strong>${avgKcal}</strong><span>Avg kcal / serve</span></div><div><strong>${avgProt}g</strong><span>Avg protein / serve</span></div></div>`:''}<section class="section"><div class="section-head"><h2>On the menu <span class="counter">${rs.length}</span></h2><button class="text-link" data-action="tab" data-value="discover">Browse recipes ↗</button></div>${daysCard()}</section>${priceSummary()}<div class="notice">${priceDisclaimer()}</div>`}
function shoppingPage(){const keys=S.shopMode==='tonight'?['tonight']:(S.shopWeeks===2?[wk(),wk(S.weekOffset+1)]:[wk()]);const list=grocery(keys),total=list.reduce((s,x)=>s+x.price,0),checkObj=S.checked[S.shopMode==='tonight'?'tonight':wk()]||{};let bought=list.filter(x=>checkObj[x.id]).length,group={};list.forEach(i=>(group[i.ing.aisle]??=[]).push(i));
return `<span class="eyebrow">EVERYTHING IN ONE PLACE</span><h1 class="hero-title">Your shopping<br><em>list.</em></h1><p class="subheading">Just what you need, grouped by aisle.</p>${S.shopMode==='tonight'?`<div class="notice">${S.tonightMeal?'Tonight: '+esc(recipe(S.tonightMeal)?.title||'Meal'):'Choose a meal from Tonight first to build this list.'}</div>`:''}<div class="shop-top"><div class="split"><div><span class="eyebrow">ESTIMATED BASKET</span><h2>${money(total)}</h2><span class="tiny muted">${list.length} items · ${esc(S.store)}</span></div><div style="font-size:45px">🧺</div></div><div class="progress"><i style="width:${list.length?100*bought/list.length:0}%"></i></div><div class="split" style="margin-top:9px;font-size:12px;color:#628260"><span>${bought} of ${list.length} picked up</span><span>${list.length?Math.round(bought/list.length*100):0}% done</span></div></div>${priceSummary()}<div class="section" style="margin-top:17px"><div class="field-row"><div class="field"><label>List for</label><select data-field="shopMode"><option value="plan" ${S.shopMode!=='tonight'?'selected':''}>My plan</option><option value="tonight" ${S.shopMode==='tonight'?'selected':''}>Tonight’s meal</option></select></div></div><div class="field-row"><div class="field"><label>Store</label><select data-field="store">${Object.keys(STORE_FACTORS).map(s=>`<option ${S.store===s?'selected':''}>${esc(s)}</option>`).join('')}</select></div><div class="field"><label>Shopping for</label><select data-field="shopWeeks" ${S.shopMode==='tonight'?'disabled':''}><option value="1" ${S.shopWeeks===1?'selected':''}>1 week</option><option value="2" ${S.shopWeeks===2?'selected':''}>2 weeks</option></select></div></div><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn light" data-action="share">↗ Share list</button><button class="btn light" data-action="add-extra">＋ Add item</button><button class="btn light" data-action="clear-checks">↺ Uncheck all</button></div></div>${list.length?Object.entries(group).map(([aisle,items])=>`<section class="aisle"><div class="aisle-head"><h3>${esc(aisle)}</h3><span>${items.length} items</span></div>${items.map(x=>{let checked=!!checkObj[x.id];let unit=x.ing.unit,amount=x.manual?`${x.qty} item${x.qty===1?'':'s'}`:`${fmtQty(x.qty)}${unit==='each'?'':' '+unit} needed · ${x.packs} ${x.packs===1?'pack':'packs'}`;return `<div class="shop-item ${checked?'bought':''}"><button class="shop-check ${checked?'checked':''}" data-action="check" data-id="${esc(x.id)}" aria-label="Toggle ${esc(x.ing.name)}">${checked?'✓':''}</button><div class="shop-name" data-action="check" data-id="${esc(x.id)}"><b>${esc(x.ing.name)}</b><small>${amount}</small>${x.matched?`<small class="live-source">✓ M&amp;S on Ocado · ${esc(x.matched.name)} · ${fmtQty(x.packSize)} ${esc(x.ing.unit)} per pack ${typeof x.matched.url==='string'&&x.matched.url.startsWith('https://www.ocado.com/')?`· <a href="${esc(x.matched.url)}" target="_blank" rel="noopener noreferrer" onclick="event.stopPropagation()">View product ↗</a>`:''}</small>${x.saved>0?`<small class="sale-highlight">🏷️ ${esc(x.offerLabel||'Price reduction')} · Save ${money(x.saved)} on ${x.packs} pack${x.packs===1?'':'s'}</small>`:''}`:`<small class="estimate-source">${x.manual?'Manually entered':'Estimated — no M&S product match'}</small>`}</div><div class="shop-price">${money(x.price)}</div>${x.manual?`<button class="round-action" data-action="del-extra" data-id="${esc(x.id)}" title="Delete">×</button>`:''}</div>`}).join('')}</section>`).join(''):`<div class="empty section"><span class="symbol">🧺</span><strong>Your list is empty</strong>Generate meals in My week to build a basket.</div>`}<div class="notice">${priceDisclaimer()} Pantry staples selected in Settings are excluded.</div>`}
function fmtQty(q){return Number.isInteger(q)?String(q):String(Math.round(q*10)/10)}
function libraryCard(r){let fav=S.favourites.includes(r.id);return `<article class="recipe-card"><button style="width:100%;display:block;padding:0;background:none" data-action="detail" data-id="${r.id}" aria-label="Open ${esc(r.title)}">${getArt(r,'recipe-art')}</button><div class="recipe-body"><span class="eyebrow" style="font-size:9px">${r.diet==='meat'?'EVERYDAY DINNER':r.diet==='fish'?'FISH & SEAFOOD':r.diet==='vegan'?'PLANT-BASED':'VEGETARIAN'}</span><div class="recipe-title">${esc(r.title)}</div><div class="recipe-meta"><span>◷ ${r.minutes} min</span><span>· ${r.kcal} kcal</span><span>· ${r.protein}g protein</span></div><div class="recipe-footer"><strong>~${money(recipeActualCost(r))}</strong><button class="heart ${fav?'liked':''}" data-action="fav" data-id="${r.id}" aria-label="Favourite">${fav?'♥':'♡'}</button></div></div></article>`}
function discoverPage(){let results=allR().filter(r=>{
  const q=S.query.toLowerCase().trim();if(q&&!(`${r.title} ${r.note} ${r.ingredients.map(x=>ingredient(x.id)?.name||'').join(' ')}`.toLowerCase().includes(q)))return false;
  if(S.filter==='favs'&&!S.favourites.includes(r.id))return false;
  if(S.filter==='quick'&&r.minutes>25)return false;
  if(S.filter==='protein'&&r.protein<32)return false;
  if(S.filter==='veggie'&&!['vegan','vegetarian'].includes(r.diet))return false;
  if(S.filter==='lowcarb'&&r.carbs>36)return false;
  return true
});let filters=[['all','All recipes'],['quick','⚡ Under 25 min'],['protein','💪 High protein'],['veggie','🥬 Veggie'],['lowcarb','Low carb'],['favs','♥ Favourites']];
return `<span class="eyebrow">FIND YOUR NEXT FAVOURITE</span><h1 class="hero-title">Good food,<br><em>good mood.</em></h1><p class="subheading">${allR().length} dinner ideas and counting. Make them your own.</p><div class="section"><div class="searchwrap"><input id="recipe-search" class="searchbox" type="search" placeholder="Search meals or ingredients..." value="${esc(S.query)}" autocomplete="off"></div><div class="toolbar" style="margin-top:13px">${filters.map(([k,v])=>`<button class="chip ${S.filter===k?'active':''}" data-action="filter" data-value="${k}">${v}</button>`).join('')}</div></div><div class="result-head"><span>${results.length} recipes</span><button class="text-link" data-action="new-recipe">＋ Add your own</button></div>${results.length?`<div class="grid-recipes">${results.map(libraryCard).join('')}</div>`:`<div class="empty"><span class="symbol">🍲</span><strong>Nothing matched</strong>Try a different search or filter.</div>`}`}
function chips(list,chosen,action){return `<div class="toolbar" style="flex-wrap:wrap;overflow:visible;margin:7px 0 3px">${list.map(([k,name])=>`<button class="chip compact ${chosen.includes(k)?'active':''}" data-action="${action}" data-value="${esc(k)}">${name}</button>`).join('')}</div>`}

function quickChoices(){
 // Use saved allergy exclusions and avoid-list even for spontaneous recipes, but allow fresh food/time choices.
 const avoid=String(S.avoid||'').toLowerCase().split(',').map(x=>x.trim()).filter(Boolean);
 return allR().filter(r=>{
  if(r.minutes>S.quickTime)return false;
  if(S.quickType==='veggie'&&!['vegetarian','vegan'].includes(r.diet))return false;
  if(S.quickType==='vegan'&&r.diet!=='vegan')return false;
  if(S.quickType==='meat'&&r.diet!=='meat')return false;
  if(S.quickType==='fish'&&r.diet!=='fish')return false;
  if(S.quickFamily&&/spicy|sriracha|firecracker|jalapeño|jalapeno/i.test(r.title))return false;
  if(S.allergens.some(a=>allergens(r).includes(a)))return false;
  if(avoid.some(t=>r.title.toLowerCase().includes(t)||r.ingredients.some(x=>ingredient(x.id)?.name.toLowerCase().includes(t))))return false;
  if(['tray','oven'].includes(r.method))return S.appliances.includes('oven')||S.appliances.includes('airfryer');
  return S.appliances.includes('hob');
 }).sort((a,b)=>{
  const score=r=> (S.quickGoal==='protein'?(r.protein||0)/15:0)+(S.quickGoal==='healthy'?(700-(r.kcal||700))/160:0)+(S.quickGoal==='budget'?-recipeActualCost(r)/3:0)+r.ingredients.reduce((n,x)=>n+((S.livePrices?.[x.id]?.wasPrice||0)>(S.livePrices?.[x.id]?.price||Infinity)?0.45:0),0);
  return (score(b)-score(a))+(Math.sin((S.quickSeed+3)*91+b.title.length*19)-Math.sin((S.quickSeed+3)*91+a.title.length*19))*1.4;
 });
}
function tonightPage(){const picks=quickChoices().slice(0,6);let types=[['any','Anything'],['meat','🍗 Meat'],['fish','🐟 Fish'],['veggie','🥦 Veggie'],['vegan','🌱 Vegan']];let goals=[['any','Any style'],['protein','High protein'],['healthy','Healthy'],['budget','Budget friendly']];return `<span class="eyebrow">AFTER-WORK DINNER, SORTED</span><h1 class="hero-title">What’s for<br><em>tonight?</em></h1><p class="subheading">No weekly planning needed. Choose the kind of meal and how much time you have.</p><section class="settings-card quick-filters"><h3>What are you in the mood for?</h3><div class="choice-grid quick-type-grid">${types.map(([v,t])=>`<button class="choice-card ${S.quickType===v?'selected':''}" data-action="quick-type" data-value="${v}">${t}</button>`).join('')}</div><div class="field-row"><div class="field"><label>Maximum total time</label><select data-field="quickTime">${[15,20,30,45,60,90,120].map(t=>`<option value="${t}" ${S.quickTime===t?'selected':''}>${t} minutes</option>`).join('')}</select></div><div class="field"><label>Optional goal</label><select data-field="quickGoal">${goals.map(([v,t])=>`<option value="${v}" ${S.quickGoal===v?'selected':''}>${t}</option>`).join('')}</select></div></div><label class="quick-family"><input type="checkbox" data-action="quick-family" ${S.quickFamily?'checked':''}> Kid-friendly / milder dishes</label><p class="wizard-help">Your saved allergens, excluded ingredients and available appliances are respected.</p></section>${S.tonightMeal?`<div class="notice">Tonight’s pick: <strong>${esc(recipe(S.tonightMeal)?.title||'Selected meal')}</strong> · <button class="text-link" data-action="quick-shopping">View one-meal shopping list →</button></div>`:''}<section class="section"><div class="section-head"><h2>${picks.length?'Ideas for tonight':'No matches yet'}</h2><button class="text-link" data-action="quick-regenerate">↻ Different ideas</button></div>${picks.length?`<div class="grid-recipes quick-grid">${picks.map(r=>`<article class="recipe-card">${getArt(r,'recipe-art')}<div class="recipe-body"><span class="eyebrow">${r.minutes} MIN · ${r.diet.toUpperCase()}</span><div class="recipe-title">${esc(r.title)}</div><div class="recipe-meta">${r.protein}g protein · Ingredients ~${money(recipeActualCost(r))}</div><div class="quick-card-actions"><button class="btn orange" data-action="quick-pick" data-id="${esc(r.id)}">Choose tonight</button><button class="btn light" data-action="detail" data-id="${esc(r.id)}">Recipe</button></div></div></article>`).join('')}</div>`:`<div class="empty"><strong>No meals match</strong>Try more time or a different meal type. Saved allergen exclusions are still applied.</div>`}</section><div class="notice">Prices shown here are approximate ingredient costs, not whole-pack basket totals. Refresh M&amp;S prices from Shopping once you've chosen a meal.</div>`}

function profilePage(){return `<span class="eyebrow">MAKE IT YOURS</span><h1 class="hero-title">Your kitchen,<br><em>your rules.</em></h1><p class="subheading">Your choices shape each new plan, however many days you choose.</p><section class="section"><div class="settings-card"><h3>✦ Your meal-planning questions</h3><p>Choose the number of days, diet, food choices, family preferences and budget.</p><button class="btn" data-action="wizard-edit">Run meal-planning questionnaire →</button></div>${priceSettings()}<div class="settings-card appearance-card"><div><h3>🌙 Appearance</h3><p>Choose the display that feels best on your eyes. Your choice is saved on this device.</p></div><button class="appearance-toggle" data-action="theme" aria-pressed="${S.theme==='dark'}"><span>${S.theme==='dark'?'☾ Dark mode':'☀ Light mode'}</span><span class="switch-track"><i></i></span></button></div><div class="settings-card"><h3>🛒 Budget and household</h3><p>Estimated UK grocery prices, sized for your household.</p><div class="field-row"><div class="field"><label>Meal-plan budget (£)</label><input type="number" min="5" max="500" step="1" value="${S.budget}" data-field="budget"></div><div class="field"><label>Preferred supermarket</label><select data-field="store">${Object.keys(STORE_FACTORS).map(s=>`<option ${S.store===s?'selected':''}>${esc(s)}</option>`).join('')}</select></div></div><div class="field"><label>People eating</label><div class="stepper"><button data-action="servings" data-value="-1" aria-label="One fewer person">−</button><strong>${S.servings}</strong><button data-action="servings" data-value="1" aria-label="One more person">＋</button></div></div></div><div class="settings-card"><h3>🥬 Dietary preferences</h3><p>Only matching recipes will be selected when you generate a week.</p><div class="field"><label>How do you eat?</label><select data-field="diet"><option value="any" ${S.diet==='any'?'selected':''}>Anything / no restriction</option><option value="vegetarian" ${S.diet==='vegetarian'?'selected':''}>Vegetarian</option><option value="vegan" ${S.diet==='vegan'?'selected':''}>Vegan</option><option value="pescatarian" ${S.diet==='pescatarian'?'selected':''}>Pescatarian</option><option value="lowcarb" ${S.diet==='lowcarb'?'selected':''}>Lower carb</option></select></div><div class="field"><label>What matters to you?</label>${chips([['quick','⚡ Quick'],['family','👨‍👩‍👧 Family friendly'],['protein','💪 More protein'],['budget','💰 Stretch my budget'],['healthy','🥗 Healthier dinners']],S.priorities,'priority')}</div><div class="field"><label>Avoid ingredients (comma-separated)</label><input data-field="avoid" value="${esc(S.avoid)}" placeholder="e.g. mushrooms, prawns" /></div><div class="field"><label>Food allergens to exclude</label>${chips(ALLERGENS.map(x=>[x,x[0].toUpperCase()+x.slice(1)]),S.allergens,'allergen')}</div><p class="fallback">Important: allergy screening uses ingredient labels only, not manufacturing or cross-contamination data. Always check packaging.</p></div><div class="settings-card"><h3>🍳 Your kitchen</h3><p>Which appliances can you use to cook?</p>${chips(APPLIANCES.map(x=>[x,x==='airfryer'?'Air fryer':x[0].toUpperCase()+x.slice(1)]),S.appliances,'appliance')}<div class="field"><label>My week starts on</label><select data-field="startDay"><option value="1" ${S.startDay===1?'selected':''}>Monday</option><option value="0" ${S.startDay===0?'selected':''}>Sunday</option></select></div></div><div class="settings-card"><h3>🧂 What you already have</h3><p>Exclude these pantry staples from grocery totals. Select what is in your cupboard.</p>${chips(['oil','salt','peppercorn','paprika','cumin','oregano','soy','honey','rice','pasta','garlic','sugar','flour','stock','curry_powder','chilli','sesame','peanut'].map(x=>[x,ING[x].name]),S.pantry,'pantry')}</div><div class="settings-card"><h3>🔐 Your data belongs to you</h3><p>Everything is saved locally on this browser. Export a backup before clearing Safari data or changing phones. No account, adverts or subscription.</p><div class="settings-footer"><button class="btn" data-action="export">↓ Export backup</button><button class="btn light" data-action="import">↑ Import backup</button><button class="btn danger" data-action="reset">Reset data</button></div><input id="backup-import" type="file" accept=".json,application/json" hidden /><p class="note" style="margin-top:13px">Plans do not automatically sync between phones. Hosted over HTTPS, this app can be added to your iPhone Home Screen and works offline after its first load.</p></div></section>`}

function priceDisclaimer(){
 if(S.store!==MS_STORE)return 'Prices are estimates and not checked against the shop.';
 const matched=Object.keys(S.livePrices||{}).length;
 return `Only matched M&amp;S products use fetched Ocado online prices and verified offers; other items remain estimates. ${matched?`Last refresh: ${esc(new Date(S.lastLiveAt).toLocaleString('en-GB'))}. `:''}Ocado prices can differ from M&amp;S Foodhall shelf prices and availability.`
}
function priceSummary(){
 if(S.store!==MS_STORE)return '';
 const entries=grocery(S.shopMode==='tonight'?['tonight']:[wk()]).filter(x=>!x.manual),found=entries.filter(x=>x.source==='live').length,total=entries.length;
 const stale=S.lastLiveAt&&Date.now()-S.lastLiveAt>PRICE_TTL;
 return `<div class="price-panel"><div class="price-panel-head"><div><strong>🛒 M&amp;S price updates</strong><small>${!S.lastLiveAt?'Not connected yet — estimates only':`${found} of ${total} shopping ingredients matched · ${stale?'Prices may be outdated':'Prices saved'}`}</small></div><button class="btn price-refresh" data-action="refresh-prices" ${priceBusy?'disabled':''}>${priceBusy?'⌛ Checking…':'↻ Refresh prices'}</button></div>${priceStatus?`<p class="price-status">${esc(priceStatus)}</p>`:''}<p class="price-footnote">Matched products and sale prices come from M&amp;S Food on Ocado, not in-store M&amp;S prices. Requires one-time setup for the pricing connection.</p></div>`
}
function priceSettings(){return `<div class="settings-card"><h3>🛒 M&amp;S live prices</h3><p>Refresh matched M&amp;S products, price cuts and eligible multibuys from Ocado. Unmatched ingredients remain clearly labelled as estimates. You need to deploy the included Netlify price function and set its secrets before refresh works.</p>${priceSummary()}<p class="note">Setup: add APIFY_TOKEN and PRICE_REFRESH_CODE under your Netlify environment variables, then redeploy. On refresh, enter the private code you chose. It is kept for this browser session only. The Apify service may charge usage fees.</p></div>`}
function autoRefreshIfNeeded(){
 if(S.tab!=='shop'||S.store!==MS_STORE||!S.lastLiveAt||Date.now()-S.lastLiveAt<PRICE_TTL||priceBusy||Date.now()-lastAutoPriceTry<60*60*1000)return;
 let code='';try{code=sessionStorage.getItem('platepilot_price_code')||''}catch(e){}
 if(!code)return;
 lastAutoPriceTry=Date.now();setTimeout(()=>refreshPrices(),500);
}
async function refreshPrices(){
 if(S.store!==MS_STORE){toast('Select M&S as the store first');return}
 if(priceBusy)return;
 if(!navigator.onLine){toast('Connect to the internet to update prices');return}
 let code='';try{code=sessionStorage.getItem('platepilot_price_code')||''}catch(e){}
 if(!code){code=prompt('Enter your private M&S price refresh code from Netlify settings:')||'';if(!code)return;}
 const basket=grocery(S.shopMode==='tonight'?['tonight']:[wk()]).filter(x=>!x.manual);
 if(!basket.length){toast('Choose or generate meals first');return;}
 // Keep requests modest to avoid unexpected third-party data charges.
 const ingredients=basket.slice(0,32).map(x=>({id:x.id,name:x.ing.name,unit:x.ing.unit}));
 const url='/.netlify/functions/prices';
 async function request(data){const res=await fetch(url,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({...data,code,ingredients}),cache:'no-store'});if(!res.ok){let msg='Price service unavailable';try{const j=await res.json();msg=j.error||msg}catch(e){if(res.status===404)msg='Price service is not deployed. See README setup.'}if(res.status===401){try{sessionStorage.removeItem('platepilot_price_code')}catch(e){}}throw new Error(msg)}return res.json()}
 priceBusy=true;priceStatus='Searching M&S Food products on Ocado…';render();
 try{
  const started=await request({action:'start'});
  try{sessionStorage.setItem('platepilot_price_code',code)}catch(e){}
  const runId=started.runId;if(!runId)throw new Error('Could not start a price check');
  let result=null;
  for(let attempt=0;attempt<45;attempt++){
   await new Promise(r=>setTimeout(r,3500));
   result=await request({action:'poll',runId});
   if(result.status==='done')break;
   if(result.status==='failed')throw new Error(result.error||'Ocado search failed');
   if(attempt===44)throw new Error('Price search is still processing. Try refreshing again later.');
  }
  const prices=result?.prices||{};
  if(!Object.keys(prices).length)throw new Error('No reliable M&S product matches found. No estimates were replaced.');
  const fresh={...(S.livePrices||{})};for(const item of ingredients)delete fresh[item.id];S.livePrices={...fresh,...prices};S.lastLiveAt=Date.now();save();
  priceStatus=`Updated ${Object.keys(prices).length} M&S ingredient prices and any available offers. Unmatched products still use estimates.`;
  toast('M&S prices updated');
 }catch(e){priceStatus=e.message||'Unable to fetch M&S prices';toast('Prices not updated')}
 finally{priceBusy=false;render()}
}
function wizardPage(){
 const goals=[['quick','⚡ Quick meals'],['healthy','🥗 Healthy & balanced'],['protein','💪 High protein'],['family','🧸 Kid-friendly'],['budget','💷 Budget-conscious']];
 const foods=[['meat','🍗 Meat'],['fish','🐟 Fish & seafood'],['egg','🥚 Eggs'],['vegetarian','🥑 Vegetarian'],['vegan','🌱 Plant based']];
 const title=['How do you like to eat?','What would you like to cook?','What matters in your day?','Let’s plan your meals.'][WIZARD_STEP];
 let content='';
 if(WIZARD_STEP===0)content=`<p class="wizard-lead">First, any dietary restrictions?</p><div class="wizard-field"><label>Diet type</label><select data-field="diet"><option value="any" ${S.diet==='any'?'selected':''}>I eat everything</option><option value="vegetarian" ${S.diet==='vegetarian'?'selected':''}>Vegetarian</option><option value="vegan" ${S.diet==='vegan'?'selected':''}>Vegan</option><option value="pescatarian" ${S.diet==='pescatarian'?'selected':''}>Pescatarian</option><option value="lowcarb" ${S.diet==='lowcarb'?'selected':''}>Lower carb</option></select></div><div class="wizard-field"><label>Any allergens to exclude?</label><p class="wizard-help">Optional. We exclude recipes containing these ingredients, but always check packaging.</p>${chips(ALLERGENS.map(x=>[x,x[0].toUpperCase()+x.slice(1)]),S.allergens,'allergen')}</div><div class="wizard-field"><label>Ingredients you want to avoid</label><input data-field="avoid" value="${esc(S.avoid)}" placeholder="e.g. mushrooms, coriander" /></div>`;
 if(WIZARD_STEP===1)content=`<p class="wizard-lead">Choose everything you'd be happy to see on your menu.</p><div class="choice-grid">${foods.map(([key,name])=>`<button class="choice-card ${(S.foods||[]).includes(key)?'selected':''}" data-action="wizard-food" data-value="${key}" aria-pressed="${(S.foods||[]).includes(key)}">${name}<span>${(S.foods||[]).includes(key)?'✓':'+'}</span></button>`).join('')}</div><p class="wizard-help">Choose at least one. We'll mix the dishes you select across the week.</p>`;
 if(WIZARD_STEP===2)content=`<p class="wizard-lead">Pick your priorities — we’ll favour recipes that suit your routine.</p><div class="choice-grid">${goals.map(([key,name])=>`<button class="choice-card ${S.priorities.includes(key)?'selected':''}" data-action="priority" data-value="${key}" aria-pressed="${S.priorities.includes(key)}">${name}<span>${S.priorities.includes(key)?'✓':'+'}</span></button>`).join('')}</div><div class="wizard-field"><label>Maximum cooking time</label><select data-field="timeCap">${[20,30,45,60,90].map(n=>`<option value="${n}" ${Number(S.timeCap)===n?'selected':''}>${n} minutes</option>`).join('')}</select></div><p class="wizard-help">Kid-friendly favours milder meals and family-style dishes. This isn't a guarantee for every child.</p>`;
 if(WIZARD_STEP===3)content=`<p class="wizard-lead">The final details help us estimate your shop and portions.</p><div class="wizard-field"><label>How many days are you planning?</label><div class="stepper"><button data-action="plan-days" data-value="-1" aria-label="One fewer day">−</button><strong>${S.planLength} ${S.planLength===1?'day':'days'}</strong><button data-action="plan-days" data-value="1" aria-label="One more day">＋</button></div><p class="wizard-help">Anywhere from 1 to 28 consecutive days, starting on your selected week. Longer plans may overlap neighbouring weeks.</p></div><div class="wizard-field"><label>How many people are eating?</label><div class="stepper"><button data-action="wizard-people" data-value="-1" aria-label="Fewer people">−</button><strong>${S.servings}</strong><button data-action="wizard-people" data-value="1" aria-label="More people">＋</button></div></div><div class="wizard-field"><label>Dinner budget for this plan</label><div class="currency-input"><span>£</span><input type="number" data-field="budget" min="5" max="500" step="5" value="${S.budget}" inputmode="decimal" /></div><p class="wizard-help">Basket totals are based on entire packs. Your budget is a target, not a guarantee.</p></div><div class="wizard-field"><label>Preferred supermarket</label><div class="store-choice">🛒 &nbsp; Marks &amp; Spencer <span>M&amp;S Food via Ocado prices (when connected)</span></div></div><div class="wizard-field"><label>Available appliances</label>${chips(APPLIANCES.map(x=>[x,x==='airfryer'?'Air fryer':x[0].toUpperCase()+x.slice(1)]),S.appliances,'appliance')}</div>`;
 return `<div class="wizard-screen"><div class="wizard-wrap"><div class="wizard-brand">${brand()}<span>YOUR WEEK, YOUR WAY.</span></div><div class="wizard-top"><div><span class="eyebrow">PERSONALISED MEAL PLANNING</span><h1>${esc(title)}</h1></div><div class="wizard-count">${WIZARD_STEP+1} / 4</div></div><div class="wizard-progress">${[0,1,2,3].map(i=>`<i class="${i<=WIZARD_STEP?'filled':''}"></i>`).join('')}</div><section class="wizard-card">${content}</section><div class="wizard-actions">${WIZARD_STEP>0?`<button class="btn light" data-action="wizard-back">← Back</button>`:S.plans&&Object.keys(S.plans).length?`<button class="btn light" data-action="wizard-cancel">Keep my current plan</button>`:''}<button class="generate" data-action="${WIZARD_STEP===3?'wizard-finish':'wizard-next'}">${WIZARD_STEP===3?'✦ Generate my ${S.planLength}-day plan':'Continue →'}</button></div><button class="btn light full wizard-tonight" data-action="skip-to-tonight">⚡ Just need one meal tonight? Skip planning →</button><p class="wizard-bottom">${allR().length} recipes · Flexible days · M&amp;S shopping list · No subscriptions · Private on your device</p></div></div>`;
}

function render(opts={}){applyTheme();if(!S.onboarded){app.innerHTML=wizardPage();document.body.classList.remove('no-scroll');window.scrollTo(0,0);return;}const scroll=window.scrollY;let pg= S.tab==='plan'?planPage():S.tab==='tonight'?tonightPage():S.tab==='shop'?shoppingPage():S.tab==='discover'?discoverPage():profilePage();app.innerHTML=shell(pg);document.body.classList.toggle('no-scroll',!!MODAL);if(opts.top)window.scrollTo(0,0);else if(!MODAL)window.scrollTo(0,scroll);if(opts.focusSearch){let el=document.getElementById('recipe-search');if(el){el.focus();el.setSelectionRange(el.value.length,el.value.length)}}autoRefreshIfNeeded()}
function modalHTML(){if(!MODAL)return '';let c='';if(MODAL.type==='recipe')c=recipeModal(MODAL.id);else if(MODAL.type==='cook')c=cookModal(MODAL.id);else if(MODAL.type==='selectday')c=selectDayModal(MODAL.id);else if(MODAL.type==='pick')c=pickModal(MODAL.day);else if(MODAL.type==='extra')c=extraModal();else if(MODAL.type==='new')c=newModal();else if(MODAL.type==='generate')c=generateModal();return `<div class="overlay" id="overlay"><div class="sheet" role="dialog" aria-modal="true" aria-label="${esc(MODAL.type)}"><button class="sheet-close" data-action="close" aria-label="Close">×</button>${c}</div></div>`}
function recipeModal(id){const r=recipe(id);if(!r)return '<div class="sheet-content">Recipe not found</div>';let likes=S.favourites.includes(id),sv=MODAL.servings||S.servings,ingPrice=recipeActualCost(r,sv);return `${getArt(r,'sheet-hero')}<div class="sheet-content"><span class="eyebrow">${r.minutes} MINUTES · ${r.diet==='meat'?'EVERYDAY DINNER':r.diet.toUpperCase()}</span><h2>${esc(r.title)}</h2><p class="subheading">${esc(r.note||'A lovely homemade meal for your weekly rotation.')}</p><p class="photo-note">Illustrative artwork · appearance may differ from the finished dish.</p><div class="macros"><div class="macro"><b>${r.kcal}</b><span>kcal / serve</span></div><div class="macro"><b>${r.protein}g</b><span>protein</span></div><div class="macro"><b>${r.carbs}g</b><span>carbs</span></div><div class="macro"><b>${r.fat}g</b><span>fat</span></div></div><div class="recipe-controls"><button class="btn orange" data-action="selectday" data-id="${id}">＋ Add to a day</button><button class="btn light" data-action="fav" data-id="${id}">${likes?'♥ Saved':'♡ Save'}</button></div><div class="split"><h3 class="sheet-mini-title">Ingredients</h3><div class="stepper"><button data-action="modal-servings" data-value="-1">−</button><strong>${sv}</strong><button data-action="modal-servings" data-value="1">＋</button></div></div><p class="tiny muted" style="margin:0 0 9px">For ${sv} ${sv===1?'person':'people'} · used amounts ~${money(ingPrice)}</p><ul class="ingredients">${r.ingredients.filter(x=>x.qty>0).map(x=>`<li><span>${esc(ingredient(x.id)?.name||x.id)}</span><span>${fmtQty(x.qty*sv/2)}${ingredient(x.id)?.unit==='each'?'':' '+(ingredient(x.id)?.unit||'g')}</span></li>`).join('')}</ul><h3 class="sheet-mini-title">How to make it</h3>${r.steps.map((step,i)=>`<div class="recipe-step"><b>${i+1}</b><span>${esc(step)}</span></div>`).join('')}<p class="note" style="margin:15px 0">Nutrition and ingredient costs are estimates. Cooking times vary; always cook meat and seafood thoroughly.</p><button class="generate" data-action="start-cook" data-id="${id}">▶ Start cooking mode</button>${String(id).startsWith('u_')?`<button class="btn danger full" style="margin-top:10px" data-action="del-recipe" data-id="${esc(id)}">Delete my recipe</button>`:''}</div>`}
function cookModal(id){let r=recipe(id);if(!r)return '';let step=Math.min(Math.max(MODAL.step||0,0),r.steps.length-1);let left=timerEnd?Math.max(0,Math.ceil((timerEnd-Date.now())/1000)):0;return `<div class="sheet-content"><span class="eyebrow">LET'S GET COOKING</span><h2>${esc(r.title)}</h2><div class="cook-mode"><span class="cook-emoji">${r.emoji}</span><span class="step-number">STEP ${step+1} OF ${r.steps.length}</span><div class="big-step">${esc(r.steps[step])}</div><div class="progress" style="width:85%;max-width:310px"><i style="width:${(step+1)/r.steps.length*100}%"></i></div><div class="cook-controls"><button class="btn light" data-action="cook-step" data-value="-1" ${step===0?'disabled':''}>← Back</button>${step<r.steps.length-1?`<button class="btn orange" data-action="cook-step" data-value="1">Next →</button>`:`<button class="btn orange" data-action="done-cook" data-id="${id}">✓ Finished</button>`}</div></div><div class="small-card" style="text-align:center;background:#f8f8f3"><div style="font-size:12px;font-weight:700;color:#73816e">IN-APP COOKING TIMER</div><div style="font-size:31px;font-weight:850;letter-spacing:-1px;margin:9px 0" id="clock-time">${clock(left)}</div><div class="split" style="justify-content:center;gap:7px"><button class="btn light" data-action="timer" data-value="300">5 min</button><button class="btn light" data-action="timer" data-value="600">10 min</button><button class="btn light" data-action="timer" data-value="900">15 min</button><button class="btn light" data-action="timer" data-value="0">Reset</button></div><p class="note">Keep the app open for the timer. Background alerts aren't guaranteed on iPhone.</p></div><button class="btn outline full" data-action="back-recipe" data-id="${id}" style="margin-top:16px">← Back to recipe</button></div>`}
function clock(sec){let m=Math.floor(sec/60),s=sec%60;return String(m).padStart(2,'0')+':'+String(s).padStart(2,'0')}
function selectDayModal(id){let r=recipe(id),dates=weekDays();return `<div class="sheet-content" style="padding-top:58px"><span class="eyebrow">CHOOSE A DINNER DATE</span><h2>Add to your plan</h2><p class="subheading">${esc(r?.title||'Choose a recipe')}</p><div class="day-grid">${dates.map((d,i)=>`<button class="day-select ${MODAL.day===i?'active':''}" data-action="selectday-index" data-day="${i}"><strong>${DAYS[d.getDay()].slice(0,2)}</strong><span>${d.getDate()}</span></button>`).join('')}</div><p class="note">Selecting a day replaces the current dinner on that date.</p><button class="generate" data-action="set-day-recipe" data-id="${esc(id)}" data-day="${MODAL.day??0}">Add to ${DAYS[dates[MODAL.day??0].getDay()]} →</button></div>`}
function pickModal(day){let pool=eligible().filter(r=>r.id!==planDays()[day]);if(!pool.length)pool=allR();let suggested=randomSample(pool,12);return `<div class="sheet-content" style="padding-top:55px"><span class="eyebrow">SWAP YOUR MEAL</span><h2>Pick something else</h2><p class="subheading">Here are some dishes matching your preferences.</p><div style="margin-top:16px">${suggested.map(r=>`<button class="option-item" data-action="pick-recipe" data-id="${r.id}" data-day="${day}">${getArt(r,'mini-art')}<b>${esc(r.title)}<small style="display:block;margin-top:5px;color:#888d84;font-weight:500">${r.minutes} min · ${r.protein}g protein</small></b><span style="color:#8c9288">›</span></button>`).join('')}</div><button class="generate secondary" data-action="random-swap" data-day="${day}">✦ Surprise me instead</button></div>`}
function extraModal(){return `<div class="sheet-content" style="padding-top:55px"><span class="eyebrow">DON'T FORGET IT</span><h2>Add to your list</h2><form id="extra-form"><div class="field"><label>What do you need?</label><input name="item" placeholder="e.g. coffee" maxlength="70" required></div><div class="field-row"><div class="field"><label>Quantity</label><input type="number" name="qty" min="1" max="99" value="1" required></div><div class="field"><label>Estimated price per item (£)</label><input type="number" name="price" min="0" max="500" step="0.01" value="1.00" required></div></div><button class="generate" type="submit">＋ Add item</button></form></div>`}
function newModal(){return `<div class="sheet-content" style="padding-top:55px"><span class="eyebrow">YOUR OWN RECIPE BOX</span><h2>Add a recipe</h2><p class="subheading">Save a family favourite, an idea from a book, or a recipe you found online.</p><form id="new-form"><div class="field"><label>Recipe name</label><input name="title" maxlength="90" placeholder="e.g. Grandma's pasta" required></div><div class="field-row"><div class="field"><label>Minutes to cook</label><input name="minutes" type="number" min="5" max="360" value="30" required></div><div class="field"><label>Type</label><select name="diet"><option value="meat">Meat</option><option value="fish">Fish</option><option value="vegetarian">Vegetarian</option><option value="vegan">Vegan</option></select></div></div><div class="field"><label>Ingredients — one per line</label><textarea name="ingredients" rows="6" required placeholder="300g chicken breast&#10;150g rice&#10;1 lemon&#10;200g broccoli"></textarea><p class="note" style="margin:0">Use grams, millilitres or whole items. Unknown items get an indicative £1.50 pack price and no nutrition.</p></div><div class="field"><label>Cooking instructions — one step per line</label><textarea name="steps" rows="6" required placeholder="Boil the rice.&#10;Cook chicken in a pan.&#10;Add vegetables and serve."></textarea></div><div class="field-row"><div class="field"><label>Calories / serving (optional)</label><input name="kcal" type="number" min="0" max="4000" placeholder="e.g. 530"></div><div class="field"><label>Protein g / serving (optional)</label><input name="protein" type="number" min="0" max="300" placeholder="e.g. 35"></div></div><button class="generate" type="submit">Save recipe</button></form></div>`}
function generateModal(){return `<div class="sheet-content" style="padding-top:58px"><span class="eyebrow">FRESH MEAL PLAN</span><h2>Regenerate your plan?</h2><p class="subheading">We'll replace the ${S.planLength} dinners for ${weekLabel()}. Your custom recipes and favourites stay saved.</p><div class="small-card" style="margin-top:20px"><div class="split"><span>Budget</span><strong>${money(S.budget)}</strong></div><hr><div class="split"><span>Cooking for</span><strong>${S.servings} people</strong></div><hr><div class="split"><span>Preferred store</span><strong>${esc(S.store)}</strong></div></div><button class="generate" data-action="confirm-generate">✦ Generate a fresh plan</button><button class="btn light full" style="margin-top:10px" data-action="close">Keep my current plan</button></div>`}
function openModal(m){MODAL=m;render();document.querySelector('.sheet')?.scrollTo(0,0)}
function closeModal(){MODAL=null;timerEnd=0;render()}
function toggleIn(arr,val){let i=arr.indexOf(val);if(i===-1)arr.push(val);else arr.splice(i,1)}
function handleAction(a,el){const val=el.dataset.value,id=el.dataset.id,day=Number(el.dataset.day),key=wk();switch(a){
  case 'theme':S.theme=S.theme==='dark'?'light':'dark';save();render();break;
  case 'tab':S.tab=val;MODAL=null;save();render({top:true});break;
  case 'plan-days':S.planLength=Math.max(1,Math.min(28,S.planLength+Number(val)));save();render();break;
  case 'quick-type':S.quickType=val;save();render();break;
  case 'quick-family':S.quickFamily=!S.quickFamily;save();render();break;
  case 'quick-regenerate':S.quickSeed++;save();render();break;
  case 'quick-pick':S.tonightMeal=id;S.shopMode='tonight';S.checked.tonight={};save();openModal({type:'recipe',id,servings:S.servings});toast('Dinner chosen — your one-meal shopping list is ready');break;
  case 'quick-shopping':S.tab='shop';S.shopMode='tonight';save();render({top:true});break;
  case 'week':S.weekOffset+=Number(val);save();render();break;
  case 'generate':S.onboarded=false;WIZARD_STEP=0;save();render({top:true});break;
  case 'wizard-edit':S.onboarded=false;WIZARD_STEP=0;save();render({top:true});break;
  case 'wizard-cancel':S.onboarded=true;save();render();break;
  case 'skip-to-tonight':S.onboarded=true;S.tab='tonight';save();render({top:true});break;
  case 'wizard-next':if(WIZARD_STEP===1&&!(S.foods||[]).length){toast('Choose at least one food type');break;}WIZARD_STEP=Math.min(3,WIZARD_STEP+1);render();break;
  case 'wizard-back':WIZARD_STEP=Math.max(0,WIZARD_STEP-1);render();break;
  case 'wizard-food':S.foods??=[];toggleIn(S.foods,val);save();render();break;
  case 'wizard-people':S.servings=Math.max(1,Math.min(10,S.servings+Number(val)));save();render();break;
  case 'wizard-finish':if(!(S.foods||[]).length){toast('Choose at least one food type');WIZARD_STEP=1;render();break;}if(!eligible().length){toast('No recipes fit. Try adjusting food or time limits.');break;}if(generate()){S.onboarded=true;S.tab='plan';save();render({top:true});toast(`Your ${S.planLength}-day meal plan is ready!`)}break;
  case 'refresh-prices':refreshPrices();break;
  case 'confirm-generate':if(generate())toast('Your new meal plan is ready');closeModal();break;
  case 'close':closeModal();break;
  case 'detail':openModal({type:'recipe',id,servings:S.servings});break;
  case 'swap':openModal({type:'pick',day});break;
  case 'choose-day':openModal({type:'pick',day});break;
  case 'pick-recipe':ensurePlan().days[day]=id;S.checked[key]={};save();closeModal();toast('Dinner updated');break;
  case 'random-swap':{const options=eligible().filter(r=>r.id!==planDays()[day]);if(options.length){ensurePlan().days[day]=options[Math.floor(Math.random()*options.length)].id;save();closeModal();toast('Swapped for a new meal')}else toast('No eligible alternative found');break}
  case 'del-recipe':if(confirm('Delete this personal recipe from your library and any weekly plans?')){S.custom=S.custom.filter(r=>r.id!==id);S.favourites=S.favourites.filter(x=>x!==id);for(const plan of Object.values(S.plans))plan.days=plan.days.map(x=>x===id?null:x);save();closeModal();toast('Recipe deleted')}break;
  case 'fav':toggleIn(S.favourites,id);save();render();toast(S.favourites.includes(id)?'Added to favourites':'Removed from favourites');break;
  case 'cooked':S.cooked[key]??={};S.cooked[key][day]=!S.cooked[key][day];save();render();toast(S.cooked[key][day]?'Bon appétit! Marked as cooked.':'Marked as not cooked');break;
  case 'selectday':openModal({type:'selectday',id,day:0});break;
  case 'selectday-index':MODAL.day=day;render();break;
  case 'set-day-recipe':ensurePlan().days[day]=id;S.checked[key]={};save();closeModal();toast('Added to '+DAYS[weekDays()[day].getDay()]);break;
  case 'modal-servings':MODAL.servings=Math.max(1,Math.min(12,(MODAL.servings||S.servings)+Number(val)));render();break;
  case 'start-cook':timerEnd=0;openModal({type:'cook',id,step:0});break;
  case 'cook-step':MODAL.step=Math.max(0,Math.min(recipe(MODAL.id).steps.length-1,MODAL.step+Number(val)));render();break;
  case 'done-cook':{const idx=planDays().indexOf(id);if(idx>=0){S.cooked[key]??={};S.cooked[key][idx]=true;save()}closeModal();toast('Great work! Dinner is done.');break}
  case 'back-recipe':openModal({type:'recipe',id,servings:S.servings});break;
  case 'timer':timerEnd=Number(val)?Date.now()+Number(val)*1000:0;render();toast(timerEnd?'Timer started — keep app open':'Timer cleared');break;
  case 'filter':S.filter=val;save();render();break;
  case 'priority':toggleIn(S.priorities,val);save();render();break;
  case 'allergen':toggleIn(S.allergens,val);save();render();break;
  case 'appliance':toggleIn(S.appliances,val);save();render();break;
  case 'pantry':toggleIn(S.pantry,val);save();render();break;
  case 'servings':S.servings=Math.max(1,Math.min(12,S.servings+Number(val)));save();render();break;
  case 'check':{const target=S.shopMode==='tonight'?'tonight':key;S.checked[target]??={};S.checked[target][id]=!S.checked[target][id];save();render();break;}
  case 'clear-checks':S.checked[S.shopMode==='tonight'?'tonight':key]={};save();render();toast('All shopping items unchecked');break;
  case 'add-extra':openModal({type:'extra'});break;
  case 'del-extra':{const target=S.shopMode==='tonight'?'tonight':key;let split=id.slice(('extra-'+target+'-').length);S.manual[target]=(S.manual[target]||[]).filter(x=>x.id!==split);save();render();break}
  case 'new-recipe':openModal({type:'new'});break;
  case 'share':shareList();break;
  case 'export':exportData();break;
  case 'import':document.getElementById('backup-import')?.click();break;
  case 'reset':if(confirm('Delete all plans, recipes, favourites and settings on this device? This cannot be undone.')){localStorage.removeItem(KEY);S=defaultState();WIZARD_STEP=0;render({top:true});toast('Data reset')}break;
}}
app.addEventListener('click',e=>{const btn=e.target.closest('[data-action]');if(btn){e.preventDefault();handleAction(btn.dataset.action,btn)}});
app.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role="button"][data-action]')){e.preventDefault();handleAction(e.target.dataset.action,e.target)}});
app.addEventListener('input',e=>{if(e.target.id==='recipe-search'){S.query=e.target.value;save();render({focusSearch:true})}});
app.addEventListener('change',e=>{const el=e.target,f=el.dataset.field;if(!f)return;let value=el.value;
  if(f==='quickTime')S.quickTime=Math.max(10,Math.min(120,Number(value)||30));
  else if(f==='quickGoal')S.quickGoal=value;
  else if(f==='quickFamily')S.quickFamily=value==='yes';
  else if(f==='budget')S.budget=Math.max(5,Math.min(500,Number(value)||55));
  else if(f==='timeCap')S.timeCap=Number(value)||45;
  else if(f==='shopWeeks'||f==='startDay')S[f]=Number(value);
  else S[f]=value;
  save();render();
});
app.addEventListener('submit',e=>{e.preventDefault();let f=e.target;if(f.id==='extra-form'){let d=new FormData(f),key=S.shopMode==='tonight'?'tonight':wk(),name=String(d.get('item')||'').trim(),qty=Number(d.get('qty')),price=Number(d.get('price'));if(!name||!Number.isFinite(price)||price<0||qty<1)return;S.manual[key]??=[];S.manual[key].push({id:Math.random().toString(36).slice(2,10),name:name.slice(0,70),qty:Math.min(99,qty),price});save();closeModal();toast('Added to shopping list')}
  if(f.id==='new-form'){try{makeCustom(f);save();closeModal();S.tab='discover';render();toast('Your recipe is saved!')}catch(err){toast(err.message)}}});
app.addEventListener('change',async e=>{if(e.target.id==='backup-import'){const file=e.target.files[0];if(!file)return;try{let d=JSON.parse(await file.text());if(!d||typeof d!=='object'||!d.plans||!Array.isArray(d.custom)||!Array.isArray(d.favourites))throw Error('Invalid PlatePilot backup');if(!confirm('Replace the data currently on this device with this backup?'))return;S={...defaultState(),...d};S.tab='profile';save();render();toast('Backup restored')}catch(e){toast('Could not import this file')}}});
app.addEventListener('click',e=>{if(e.target.id==='overlay')closeModal()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&MODAL)closeModal()});
function normalizeName(s){return s.toLowerCase().replace(/[^a-z0-9]/g,'').replace(/s$/,'')}
function makeCustom(form){const d=new FormData(form),title=String(d.get('title')||'').trim().slice(0,90),minutes=Number(d.get('minutes'))||30,diet=String(d.get('diet')||'meat');if(!title)throw Error('Add a recipe name');let lines=String(d.get('ingredients')||'').split('\n').map(s=>s.trim()).filter(Boolean),steps=String(d.get('steps')||'').split('\n').map(s=>s.trim()).filter(Boolean);if(!lines.length||!steps.length)throw Error('Add ingredients and steps');let ing=[];for(let line of lines){let m=line.match(/^(\d+(?:\.\d+)?)\s*(g|kg|ml|l|each|pcs|x)?\s*(.+)$/i);if(!m)throw Error('Ingredient format: 200g broccoli');let q=Number(m[1]),unit=(m[2]||'each').toLowerCase(),name=m[3].trim();if(unit==='kg')q*=1000,unit='g';if(unit==='l')q*=1000,unit='ml';if(unit==='pcs'||unit==='x')unit='each';let match=Object.values({...ING,...S.customIngredients}).find(x=>normalizeName(x.name)===normalizeName(name))||Object.values(ING).find(x=>normalizeName(x.name).includes(normalizeName(name))&&name.length>3);let id;if(match&&match.unit===unit)id=match.id;else{ id='c_'+normalizeName(name).slice(0,20)+'_'+unit;S.customIngredients[id]??={id,name,unit,pack:unit==='each'?Math.max(1,q):Math.max(100,q),price:1.5,aisle:'Other ingredients',allergens:[],kcal:0,p:0,c:0,f:0}}
  ing.push({id,qty:q});}
  const r={id:'u_'+Date.now()+'_'+Math.random().toString(36).slice(2,6),title,emoji:'🍽️',minutes,diet,method:'stew',ingredients:ing,tags:minutes<=25?['quick']:[],note:'My own recipe',steps:steps.slice(0,30),kcal:Number(d.get('kcal'))||0,protein:Number(d.get('protein'))||0,carbs:0,fat:0};S.custom.push(r)}
function shopText(){let keys=S.shopMode==='tonight'?['tonight']:(S.shopWeeks===2?[wk(),wk(S.weekOffset+1)]:[wk()]),list=grocery(keys),checked=S.checked[S.shopMode==='tonight'?'tonight':wk()]||{},groups={};for(let item of list)(groups[item.ing.aisle]??=[]).push(item);return `PlatePilot shopping list · ${S.shopMode==='tonight'?'Tonight':weekLabel()}\nStore: ${S.store} · Est. ${money(groceryTotal(keys))}\n\n`+Object.entries(groups).map(([aisle,items])=>aisle+'\n'+items.map(x=>`${checked[x.id]?'[x]':'[ ]'} ${x.ing.name} — ${fmtQty(x.qty)}${x.ing.unit==='each'?'':' '+x.ing.unit} (${x.packs} packs) ${money(x.price)}`).join('\n')).join('\n\n')+'\n\nPrices are illustrative.'}
async function shareList(){let txt=shopText();if(navigator.share){try{await navigator.share({title:'PlatePilot groceries',text:txt});return}catch(e){if(e.name==='AbortError')return}}if(navigator.clipboard){try{await navigator.clipboard.writeText(txt);toast('Shopping list copied');return}catch(e){}}const blob=new Blob([txt],{type:'text/plain'});download(blob,'platepilot-shopping.txt');toast('Shopping list downloaded')}
function download(blob,name){let u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function exportData(){download(new Blob([JSON.stringify(S,null,2)],{type:'application/json'}),'platepilot-backup-'+localDate(new Date())+'.json');toast('Backup exported')}
let lastTimerDone=false;timerTick=setInterval(()=>{if(!MODAL||MODAL.type!=='cook'||!timerEnd)return;const left=Math.max(0,Math.ceil((timerEnd-Date.now())/1000)),el=document.getElementById('clock-time');if(el)el.textContent=clock(left);if(left===0&&!lastTimerDone){lastTimerDone=true;timerEnd=0;toast('⏰ Cooking timer finished!')}else if(left>0)lastTimerDone=false},800);
render();
if('serviceWorker' in navigator&&location.protocol==='https:'){window.addEventListener('load',()=>navigator.serviceWorker.register('sw.js').catch(()=>{}))}
